function rolloutBounds(replicas, maxSurge, maxUnavailable) {
  const pct = (v) => replicas * parseFloat(v) / 100;
  const surge = maxSurge.endsWith("%") ? Math.ceil(pct(maxSurge)) : parseInt(maxSurge, 10);
  const unavailable = maxUnavailable.endsWith("%") ? Math.floor(pct(maxUnavailable)) : parseInt(maxUnavailable, 10);
  return [replicas + surge, replicas - unavailable];
}

