function allowedDisruptions(expected, healthy, minAvailable) {
  const min = minAvailable.endsWith("%")
    ? Math.ceil(expected * parseFloat(minAvailable) / 100)
    : parseInt(minAvailable, 10);
  return Math.max(0, healthy - min);
}

def unpinned(images):
    out = []
    for image in images:
        if "@" in image:
            continue
        last = image.rsplit("/", 1)[-1]
        if ":" not in last or last.split(":", 1)[1] == "latest":
            out.append(image)
    return out
